package net.officefloor.hq.app.period;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.MapKeyColumn;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.Map;

/**
 * A period on a sheet: a name and a from and to date, both inclusive. A closed period keeps the
 * due-total it had when it was closed, and each person's due-total and carried figure for it at that moment; so does a
 * soft-closed one, whose claims can still change.
 */
@Entity
@Table(name = "period")
public class Period {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

    @Column(name = "from_date", nullable = false)
    private LocalDate fromDate;

    @Column(name = "to_date", nullable = false)
    private LocalDate toDate;

    @Column(name = "closed", nullable = false)
    private boolean closed;

    /** Soft-closed: the figures are fixed as for a closed period, but its claims can still change. */
    @Column(name = "soft_closed", nullable = false)
    private boolean softClosed;

    @Column(name = "closed_due")
    private BigDecimal closedDue;

    /** Each person's due-total fixed when the period was closed, by person id; empty while open. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "period_person_due", joinColumns = @JoinColumn(name = "period_id"))
    @MapKeyColumn(name = "person_id")
    @Column(name = "due", nullable = false)
    private Map<Long, BigDecimal> closedDues = new HashMap<>();

    /** Each person's carried figure fixed when the period was closed, by person id; empty while open. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "period_person_carried", joinColumns = @JoinColumn(name = "period_id"))
    @MapKeyColumn(name = "person_id")
    @Column(name = "carried", nullable = false)
    private Map<Long, BigDecimal> closedCarried = new HashMap<>();

    /** Each person's opening balance for the period, added to their carried figure into it, by person id. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "period_person_opening", joinColumns = @JoinColumn(name = "period_id"))
    @MapKeyColumn(name = "person_id")
    @Column(name = "opening", nullable = false)
    private Map<Long, BigDecimal> openings = new HashMap<>();

    /** The last number given to a claim opened in this period under numbering per period. */
    @Column(name = "last_claim_number", nullable = false)
    private int lastClaimNumber;

    /** At most this many OPEN or PENDING claims per person may be in the period; null for no cap. */
    @Column(name = "claim_cap")
    private Integer claimCap;

    protected Period() {
    }

    public Period(String sheetId, String name, LocalDate fromDate, LocalDate toDate) {
        this.sheetId = sheetId;
        this.name = name;
        this.fromDate = fromDate;
        this.toDate = toDate;
    }

    public Period(String sheetId, String name, LocalDate fromDate, LocalDate toDate, Integer claimCap) {
        this(sheetId, name, fromDate, toDate);
        this.claimCap = claimCap;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    public LocalDate getFromDate() {
        return fromDate;
    }

    public LocalDate getToDate() {
        return toDate;
    }

    public Integer getClaimCap() {
        return claimCap;
    }

    public boolean isClosed() {
        return closed;
    }

    public boolean isSoftClosed() {
        return softClosed;
    }

    public BigDecimal getClosedDue() {
        return closedDue;
    }

    public Map<Long, BigDecimal> getClosedDues() {
        return closedDues;
    }

    public Map<Long, BigDecimal> getClosedCarried() {
        return closedCarried;
    }

    public Map<Long, BigDecimal> getOpenings() {
        return openings;
    }

    /** Add an amount to a person's opening balance for the period. */
    public void addOpening(long personId, BigDecimal amount) {
        openings.merge(personId, amount, BigDecimal::add);
    }

    /** Give out the next claim number within this period. */
    public int nextClaimNumber() {
        return ++lastClaimNumber;
    }

    /**
     * Close the period, fixing each person's due-total and carried figure for it at this moment; its
     * own due-total is the sum of their due-totals.
     */
    public void close(Map<Long, BigDecimal> dues, Map<Long, BigDecimal> carried) {
        fix(dues, carried);
        this.closed = true;
        this.softClosed = false;
    }

    /**
     * Soft-close the period, fixing its figures as {@link #close} does while its claims can still
     * change.
     */
    public void softClose(Map<Long, BigDecimal> dues, Map<Long, BigDecimal> carried) {
        fix(dues, carried);
        this.softClosed = true;
    }

    private void fix(Map<Long, BigDecimal> dues, Map<Long, BigDecimal> carried) {
        this.closedDues.clear();
        this.closedDues.putAll(dues);
        this.closedCarried.clear();
        this.closedCarried.putAll(carried);
        this.closedDue = dues.values().stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
    }

    /** Reopen the period: its due-total is live again. */
    public void reopen() {
        this.closed = false;
        this.softClosed = false;
        this.closedDue = null;
        this.closedDues.clear();
        this.closedCarried.clear();
    }
}
package net.officefloor.hq.app.period;

import java.time.LocalDate;
import java.time.YearMonth;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.role.RoleService;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/**
 * The sheet's periods: added on the screen, each a name unique on the sheet (without regard to
 * case) and a from and to date, both inclusive; no two periods on a sheet overlap. A period can be
 * closed once: closing fixes its due-total at that moment, and no claim whose due-by is inside a
 * closed period can be added, edited, opened, settled or voided. A steward can reopen a closed period, which
 * makes its due-total live again. A period can instead be soft-closed: its figures are fixed in the
 * same way but its claims can still change; it can then be closed (fixing them afresh) or reopened. With grace days set, a change of the sheet's today closes the
 * periods past them (see {@link SheetService#setToday}).
 */
@Service
public class PeriodService {

    private final PeriodRepository periods;
    private final SheetService sheets;
    private final SheetRepository sheetRows;
    private final Audit audit;
    private final RoleService roles;

    public PeriodService(PeriodRepository periods, SheetService sheets, SheetRepository sheetRows, Audit audit,
            RoleService roles) {
        this.roles = roles;
        this.periods = periods;
        this.sheets = sheets;
        this.sheetRows = sheetRows;
        this.audit = audit;
    }

    @Transactional(readOnly = true)
    public List<Period> list(String sheetId) {
        return periods.findBySheetIdOrderByFromDateAsc(sheetId);
    }

    @Transactional
    public Period add(String sheetId, String user, String name, LocalDate from, LocalDate to, Integer cap) {
        roles.refuseViewer(sheetId, user);
        if (cap != null && cap < 1) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A period's cap must be a whole number above 0.");
        }
        if (to.isBefore(from)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A period's to-date cannot be before its from-date.");
        }
        sheets.load(sheetId, user);
        // hold the sheet so two periods added at the same moment are checked one after the other
        sheetRows.findLockedById(sheetId);
        if (periods.existsBySheetIdAndNameIgnoreCase(sheetId, name)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period name is already in use on this sheet.");
        }
        if (periods.existsBySheetIdAndFromDateLessThanEqualAndToDateGreaterThanEqual(sheetId, to, from)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period overlaps another.");
        }
        Period added;
        try {
            added = periods.saveAndFlush(new Period(sheetId, name, from, to, cap));
        } catch (DataIntegrityViolationException e) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period name is already in use on this sheet.");
        }
        audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user + " period=" + added.getName() + " from="
                + added.getFromDate() + " to=" + added.getToDate()
                + (added.getClaimCap() != null ? " cap=" + added.getClaimCap() : ""));
        return added;
    }

    /**
     * Generate one period per calendar month from the from-date's month to the to-date's month, each
     * running from the first to the last day of its month and named yyyy-mm. A month whose name is
     * already a period, or whose days overlap a period on the sheet, is left out; the others are
     * still made. Refused (400) when the to-date is before the from-date.
     */
    @Transactional
    public List<Period> generate(String sheetId, String user, LocalDate from, LocalDate to) {
        roles.refuseViewer(sheetId, user);
        if (to.isBefore(from)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The to-date cannot be before the from-date.");
        }
        sheets.load(sheetId, user);
        // hold the sheet so periods added at the same moment are checked one after the other
        sheetRows.findLockedById(sheetId);
        List<Period> made = new ArrayList<>();
        for (YearMonth month = YearMonth.from(from); !month.isAfter(YearMonth.from(to)); month = month.plusMonths(1)) {
            String name = month.toString();
            LocalDate first = month.atDay(1);
            LocalDate last = month.atEndOfMonth();
            if (periods.existsBySheetIdAndNameIgnoreCase(sheetId, name)
                    || periods.existsBySheetIdAndFromDateLessThanEqualAndToDateGreaterThanEqual(sheetId, last, first)) {
                continue;
            }
            Period added = periods.saveAndFlush(new Period(sheetId, name, first, last));
            audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user + " period=" + added.getName()
                    + " from=" + added.getFromDate() + " to=" + added.getToDate());
            made.add(added);
        }
        return made;
    }

    /**
     * Generate the twelve monthly periods of the fiscal year named FY&lt;year&gt;: from the first day
     * of the sheet's fiscal start month in that year, exactly as {@link #generate} does.
     */
    @Transactional
    public List<Period> generateFiscalYear(String sheetId, String user, int year) {
        roles.refuseViewer(sheetId, user);
        LocalDate first = LocalDate.of(year, sheets.load(sheetId, user).getFiscalStartMonth(), 1);
        return generate(sheetId, user, first, first.plusMonths(11));
    }

    /** The fiscal year each of the sheet's periods falls in (by its from-date), by period id. */
    @Transactional(readOnly = true)
    public Map<Long, String> fiscalYears(String sheetId, List<Period> list) {
        int startMonth = sheetRows.findById(sheetId).map(Sheet::getFiscalStartMonth).orElse(1);
        Map<Long, String> years = new HashMap<>();
        list.forEach(p -> years.put(p.getId(), Sheet.fiscalYearOf(p.getFromDate(), startMonth)));
        return years;
    }

    /** Close a period, fixing its due-total now; refused (403) for a role the permission matrix does not allow and (409) when it is already closed. */
    @Transactional
    public Period close(String sheetId, String user, long id) {
        roles.refuseUnlessPermitted(sheetId, user, "close");
        // hold the sheet so no claim changes while the period's due-total is fixed
        sheetRows.findLockedById(sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such sheet."));
        Period period = periods.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet."));
        if (period.isClosed()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period is already closed.");
        }
        return sheets.closePeriod(sheetId, user, period, false);
    }

    /**
     * Soft-close a period, fixing its due-total and each person's now while claims dated inside it
     * can still change; refused (403) for a role the permission matrix does not allow to close and
     * (409) when it is already closed or soft-closed.
     */
    @Transactional
    public Period softClose(String sheetId, String user, long id) {
        roles.refuseUnlessPermitted(sheetId, user, "close");
        // hold the sheet so no claim changes while the period's due-total is fixed
        sheetRows.findLockedById(sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such sheet."));
        Period period = periods.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet."));
        if (period.isClosed() || period.isSoftClosed()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period is already closed.");
        }
        return sheets.softClosePeriod(sheetId, user, period);
    }

    /**
     * Reopen a closed or soft-closed period, making its due-total live again; refused (403) for a role the
     * permission matrix does not allow and (409) when the period is not closed.
     */
    @Transactional
    public Period reopen(String sheetId, String user, long id) {
        sheetRows.findLockedById(sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such sheet."));
        Period period = periods.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet."));
        roles.refuseUnlessPermitted(sheetId, user, "reopen");
        if (!period.isClosed() && !period.isSoftClosed()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period is not closed.");
        }
        period.reopen();
        Period saved = periods.saveAndFlush(period);
        audit.recordOnCommit("PERIOD_REOPENED sheet=" + sheetId + " by=" + user + " period=" + saved.getName());
        return saved;
    }

    /**
     * Refuse (423) a change to a claim due (by its due-by) inside a closed period. Holds the sheet first, so a
     * period cannot close while the change is under way.
     */
    public void refuseIfClosed(String sheetId, LocalDate date) {
        if (isClosed(sheetId, date)) {
            throw new ResponseStatusException(HttpStatus.LOCKED, "That claim's date is inside a closed period.");
        }
    }

    /**
     * Whether a claim due by this day lies inside a closed period. Holds the sheet first, so a
     * period cannot close while a change that relies on the answer is under way.
     */
    public boolean isClosed(String sheetId, LocalDate date) {
        sheetRows.findLockedById(sheetId);
        return periods.existsBySheetIdAndClosedTrueAndFromDateLessThanEqualAndToDateGreaterThanEqual(sheetId, date,
                date);
    }

    /** The period on the sheet a claim due by this day belongs to, if any. */
    public Optional<Period> on(String sheetId, LocalDate date) {
        return periods.findBySheetIdAndFromDateLessThanEqualAndToDateGreaterThanEqual(sheetId, date, date);
    }

    /** Whether a claim due by this day lies inside a soft-closed period. */
    public boolean isSoftClosed(String sheetId, LocalDate date) {
        return periods.existsBySheetIdAndSoftClosedTrueAndFromDateLessThanEqualAndToDateGreaterThanEqual(sheetId,
                date, date);
    }
}
package net.officefloor.hq.app.period;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Positive;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/** Listing, adding, generating, closing, soft-closing and reopening the periods on a sheet. */
@RestController
@RequestMapping("/api/periods")
public class PeriodController {

    public record ListPeriodsRequest(@NotBlank @Size(max = 100) String sheet) {
    }

    /** A period's name has no spaces: it is written into the audit record as one field. */
    public record AddPeriodRequest(@NotBlank @Size(max = 100) String sheet, @NotBlank @Size(max = 100) String user,
            @NotBlank @Size(max = 100) @Pattern(regexp = "\\s*\\S+\\s*") String name, @NotNull LocalDate from,
            @NotNull LocalDate to, @Positive Integer cap) {
    }

    public record GeneratePeriodsRequest(@NotBlank @Size(max = 100) String sheet,
            @NotBlank @Size(max = 100) String user, @NotNull LocalDate from, @NotNull LocalDate to) {
    }

    /** The fiscal year to generate, by the calendar year its first day falls in. */
    public record GenerateFiscalYearRequest(@NotBlank @Size(max = 100) String sheet,
            @NotBlank @Size(max = 100) String user, @NotBlank @Pattern(regexp = "\\s*\\d{4}\\s*") String year) {
    }

    public record ClosePeriodRequest(@NotBlank @Size(max = 100) String sheet, @NotBlank @Size(max = 100) String user,
            @NotNull Long id) {
    }

    /** Lines of name,period,amount. */
    public record ImportOpeningsRequest(@NotBlank @Size(max = 100) String sheet,
            @NotBlank @Size(max = 100) String user, @NotNull @Size(max = 100_000) String text) {
    }

    /** What a paste of opening balances did: how many lines went through, and the sheet's periods now. */
    public record ImportOpeningsResponse(int count, List<PeriodResponse> periods) {
    }

    /**
     * closedDue is the due-total fixed when the period was closed, closedDues each person's (by
     * person id); null while it is open. fy is the fiscal year its from-date falls in; cap its
     * claim cap per person, null for none. closedCarried is each person's carried figure fixed when it
     * was closed (by person id); null while it is open. openings is each person's opening balance for
     * it (by person id), added to their carried figure into it.
     */
    public record PeriodResponse(long id, String name, LocalDate from, LocalDate to, boolean closed,
            boolean softClosed, String closedDue, Map<String, String> closedDues, String fy, Integer cap,
            Map<String, String> closedCarried, Map<String, String> openings) {
    }

    private PeriodResponse response(String sheetId, Period period) {
        return responses(sheetId, List.of(period)).get(0);
    }

    private List<PeriodResponse> responses(String sheetId, List<Period> list) {
        Map<Long, String> years = service.fiscalYears(sheetId, list);
        return list.stream().map(period -> new PeriodResponse(period.getId(), period.getName(), period.getFromDate(),
                period.getToDate(), period.isClosed(), period.isSoftClosed(),
                period.getClosedDue() == null ? null
                        : period.getClosedDue().setScale(2, RoundingMode.UNNECESSARY).toPlainString(),
                period.isClosed() || period.isSoftClosed() ? closedDues(period) : null, years.get(period.getId()),
                period.getClaimCap(), period.isClosed() || period.isSoftClosed() ? figures(period.getClosedCarried()) : null,
                figures(period.getOpenings())))
                .toList();
    }

    private static Map<String, String> closedDues(Period period) {
        return figures(period.getClosedDues());
    }

    private static Map<String, String> figures(Map<Long, BigDecimal> byPerson) {
        Map<String, String> dues = new TreeMap<>();
        byPerson.forEach((person, due) -> dues.put(String.valueOf(person),
                due.setScale(2, RoundingMode.UNNECESSARY).toPlainString()));
        return dues;
    }

    private final PeriodService service;
    private final OpeningImportService openings;

    public PeriodController(PeriodService service, OpeningImportService openings) {
        this.service = service;
        this.openings = openings;
    }

    @PostMapping("/list")
    public List<PeriodResponse> list(@Valid @RequestBody ListPeriodsRequest req) {
        return responses(req.sheet().trim(), service.list(req.sheet().trim()));
    }

    @PostMapping("/add")
    public PeriodResponse add(@Valid @RequestBody AddPeriodRequest req) {
        return response(req.sheet().trim(), service.add(req.sheet().trim(), req.user().trim(), req.name().trim(), req.from(), req.to(), req.cap()));
    }

    /** The periods made, by from-date. */
    @PostMapping("/generate")
    public List<PeriodResponse> generate(@Valid @RequestBody GeneratePeriodsRequest req) {
        return responses(req.sheet().trim(), service.generate(req.sheet().trim(), req.user().trim(), req.from(), req.to()));
    }

    /** The periods made for the fiscal year, by from-date. */
    @PostMapping("/generate-fy")
    public List<PeriodResponse> generateFiscalYear(@Valid @RequestBody GenerateFiscalYearRequest req) {
        return responses(req.sheet().trim(), service.generateFiscalYear(req.sheet().trim(), req.user().trim(),
                Integer.parseInt(req.year().trim())));
    }

    @PostMapping("/openings")
    public ImportOpeningsResponse importOpenings(@Valid @RequestBody ImportOpeningsRequest req) {
        String sheet = req.sheet().trim();
        int count = openings.importOpenings(sheet, req.user().trim(), req.text());
        return new ImportOpeningsResponse(count, responses(sheet, service.list(sheet)));
    }

    @PostMapping("/reopen")
    public PeriodResponse reopen(@Valid @RequestBody ClosePeriodRequest req) {
        return response(req.sheet().trim(), service.reopen(req.sheet().trim(), req.user().trim(), req.id()));
    }

    @PostMapping("/soft-close")
    public PeriodResponse softClose(@Valid @RequestBody ClosePeriodRequest req) {
        return response(req.sheet().trim(), service.softClose(req.sheet().trim(), req.user().trim(), req.id()));
    }

    @PostMapping("/close")
    public PeriodResponse close(@Valid @RequestBody ClosePeriodRequest req) {
        return response(req.sheet().trim(), service.close(req.sheet().trim(), req.user().trim(), req.id()));
    }
}
-- A period can be soft-closed: its due-total and each person's due-total for it are fixed at that
-- moment (in closed_due and period_person_due, as for a closed period), but claims dated inside it
-- can still be added, edited, opened, settled and voided. Closing or reopening it clears the flag.
ALTER TABLE period ADD COLUMN soft_closed BOOLEAN DEFAULT FALSE NOT NULL;
-- A claim added while the period its date falls in was soft-closed is a late entry.
ALTER TABLE claim ADD COLUMN late_entry BOOLEAN DEFAULT FALSE NOT NULL;
-- An OPEN or PENDING claim can be held and released again. While held it counts in no live total,
-- as a held person's open claims do, unless a statement binds it. held_on is the sheet's today when
-- it was last held.
ALTER TABLE claim ADD COLUMN held BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE claim ADD COLUMN held_on DATE;

